def two_sum(nums, target):
    seen = {}
    for i, num in enumerate(nums):
        comp = target - num
        if comp in seen:
            return [seen[comp], i]
        seen[num] = i
    return []

def max_subarray(nums):
    best = cur = nums[0]
    for x in nums[1:]:
        cur = max(x, cur + x)
        best = max(best, cur)
    return best

def missing_number(nums):
    n = len(nums)
    return n * (n + 1) // 2 - sum(nums)

def valid_parentheses(s):
    st = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for c in s:
        if c in '([{':
            st.append(c)
        elif not st or st.pop() != pairs[c]:
            return False
    return not st

def climbing_stairs(n):
    if n <= 2:
        return n
    a, b = 1, 2
    for _ in range(3, n + 1):
        a, b = b, a + b
    return b

def coin_change(coins, amount):
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for c in coins:
            if c <= i:
                dp[i] = min(dp[i], dp[i - c] + 1)
    return -1 if dp[amount] > amount else dp[amount]

def merge_intervals(intervals):
    if not intervals:
        return []
    intervals.sort()
    res = [intervals[0][:]]
    for s, e in intervals[1:]:
        if s <= res[-1][1]:
            res[-1][1] = max(res[-1][1], e)
        else:
            res.append([s, e])
    return res

def first_unique_char(s):
    from collections import Counter
    c = Counter(s)
    return next((i for i, ch in enumerate(s) if c[ch] == 1), -1)

def binary_search(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        m = (lo + hi) // 2
        if nums[m] == target:
            return m
        if nums[m] < target:
            lo = m + 1
        else:
            hi = m - 1
    return -1

def group_anagrams(words):
    groups = {}
    for w in words:
        key = ''.join(sorted(w))
        groups.setdefault(key, []).append(w)
    return [sorted(g) for g in groups.values()]

def roman_to_int(s):
    vals = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    total, prev = 0, 0
    for ch in reversed(s):
        v = vals[ch]
        total += -v if v < prev else v
        prev = v
    return total

def max_profit(prices):
    if not prices:
        return 0
    min_price = prices[0]
    best = 0
    for p in prices[1:]:
        best = max(best, p - min_price)
        min_price = min(min_price, p)
    return best

def single_number(nums):
    out = 0
    for x in nums:
        out ^= x
    return out

def longest_common_prefix(strs):
    if not strs:
        return ''
    pre = strs[0]
    for s in strs[1:]:
        while not s.startswith(pre):
            pre = pre[:-1]
            if not pre:
                return ''
    return pre

def majority_element(nums):
    cand, count = None, 0
    for x in nums:
        if count == 0:
            cand, count = x, 1
        elif x == cand:
            count += 1
        else:
            count -= 1
    return cand

def count_bits(n):
    ans = [0] * (n + 1)
    for i in range(1, n + 1):
        ans[i] = ans[i >> 1] + (i & 1)
    return ans

def has_cycle(arr):
    slow = fast = 0
    n = len(arr)
    if n == 0:
        return False
    while True:
        if fast is None or fast >= n or arr[fast][1] is None or slow is None or slow >= n:
            return False
        slow = arr[slow][1]
        fast = arr[fast][1]
        if fast is None or fast >= n:
            return False
        fast = arr[fast][1]
        if slow == fast:
            return True

def is_palindrome(x):
    if x < 0:
        return False
    s = str(x)
    return s == s[::-1]

def plus_one(digits):
    for i in range(len(digits) - 1, -1, -1):
        if digits[i] < 9:
            digits[i] += 1
            return digits
        digits[i] = 0
    return [1] + digits

def my_sqrt(x):
    if x < 0:
        return None
    lo, hi = 0, x
    while lo <= hi:
        m = (lo + hi) // 2
        if m * m <= x < (m + 1) * (m + 1):
            return m
        if m * m < x:
            lo = m + 1
        else:
            hi = m - 1
    return 0

def diagonal_sum(mat):
    n = len(mat)
    s = 0
    for i in range(n):
        s += mat[i][i]
        if n - 1 - i != i:
            s += mat[i][n - 1 - i]
    return s

def fizz_buzz(n):
    out = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            out.append('FizzBuzz')
        elif i % 3 == 0:
            out.append('Fizz')
        elif i % 5 == 0:
            out.append('Buzz')
        else:
            out.append(str(i))
    return out
